// Package mysql turns MySQL on for an application generated by Clarity:
// importing it is enough.
//
//	import _ "github.com/petervdpas/Clarity/runtimes/go/mysql"
//
// Through go-sql-driver/mysql: decimals are DECIMAL, dates DATE and
// DATETIME, bools BOOLEAN. The location is a URL
// (mysql://user:password@host:port/database) or the driver's own form.
// MySQL cannot undo changes to tables, so a migration step that fails
// halfway keeps what ran before the failure, and says so.
package mysql

import (
	"database/sql"
	"errors"
	"net/url"
	"strings"

	"github.com/go-sql-driver/mysql"
	"github.com/petervdpas/Clarity/runtimes/go/clarity"
)

func init() { clarity.UseServer(clarity.Mysql, open) }

// config reads a location: a URL, or the driver's own form as it is.
func config(location string) (*mysql.Config, error) {
	rest, ok := strings.CutPrefix(location, "mysql://")
	if !ok {
		return mysql.ParseDSN(location)
	}
	u, err := url.Parse("mysql://" + rest)
	if err != nil {
		return nil, err
	}
	c := mysql.NewConfig()
	c.Net = "tcp"
	c.Addr = u.Host
	if u.Port() == "" {
		c.Addr = u.Hostname() + ":3306"
	}
	c.User = u.User.Username()
	c.Passwd, _ = u.User.Password()
	c.DBName = strings.TrimPrefix(u.Path, "/")
	return c, nil
}

func open(location string) (clarity.Server, error) {
	c, err := config(location)
	if err != nil {
		return clarity.Server{}, err
	}
	c.ParseTime = true
	connector, err := mysql.NewConnector(c)
	if err != nil {
		return clarity.Server{}, err
	}
	// A row is referred to (1451, 1217), or refers to nothing (1452, 1216).
	isReference := func(err error) bool {
		var e *mysql.MySQLError
		if !errors.As(err, &e) {
			return false
		}
		switch e.Number {
		case 1216, 1217, 1451, 1452:
			return true
		}
		return false
	}
	return clarity.Server{DB: sql.OpenDB(connector), IsReference: isReference, Value: clarity.AsTime}, nil
}
